        "rubric": "a) Vì C nằm giữa A và B nên AC + CB = AB, suy ra CB = 6 - 2 = 4 cm (0.5đ). b) M là trung điểm CB nên CM = CB / 2 = 2 cm. Vì C nằm giữa A và M nên AM = AC + CM = 2 + 2 = 4 cm (0.5đ)."
