        "rubric": "a) Trên nửa mặt phẳng bờ Ox, vì góc xOy (50°) < góc xOz (100°) nên tia Oy nằm giữa Ox và Oz (0.25đ). b) Suy ra góc xOy + góc yOz = góc xOz => góc yOz = 100° - 50° = 50° (0.5đ). c) Vì Oy nằm giữa và góc xOy = góc yOz = 50° nên Oy là tia phân giác của góc xOz (0.25đ)."
