        "question": "Cho đoạn thẳng $AB = 12$ cm. Lấy điểm $M$ nằm giữa $A$ và $B$ sao cho $AM = 6$ cm. Điểm $M$ có phải là trung điểm của đoạn thẳng $AB$ không? Vì sao?",
        "rubric": "Vì M nằm giữa A và B nên AM + MB = AB (0.25đ).\nSuy ra MB = AB - AM = (12) - (6) = 6 (cm) (0.25đ).\nTa thấy M nằm giữa A, B và MA = MB = 6 cm (0.25đ).\nVậy điểm M chính là trung điểm của đoạn thẳng AB (0.25đ)."
