        "rubric": "Khoảng cách giữa hai cột mốc liên tiếp là 10 mét (0.25đ).\nSố khoảng cách giữa các cột mốc là: (70) : 10 = 7 (khoảng) (0.25đ).\nSố cột mốc = Số khoảng + 1 = 7 + 1 = 8 (cột) (0.25đ).\nKết luận có tất cả 8 cột mốc trên tuyến đường (0.25đ)."
