        "rubric": "Khoảng cách giữa hai cột mốc liên tiếp là 10 mét (0.25đ).\nSố khoảng cách giữa các cột mốc là: (100) : 10 = 10 (khoảng) (0.25đ).\nSố cột mốc = Số khoảng + 1 = 10 + 1 = 11 (cột) (0.25đ).\nKết luận có tất cả 11 cột mốc trên tuyến đường (0.25đ)."
